public void Receive(ShowWindowMessage message) => DispatcherQueue.TryEnqueue(() => ShowWindowOnUiThread(message));

private void ShowWindowOnUiThread(ShowWindowMessage message)
{
    _isLoadedFromDock = false;
    ResetSessionCounters();
    ShowHwnd(message.Hwnd, settings.SummonOn);
}

private void UpdateSessionOnUiThread(Action update)
{
    if (DispatcherQueue.HasThreadAccess)
    {
        update();
        return;
    }

    DispatcherQueue.TryEnqueue(update);
}

